fun displayName(raw: String?): String {
    val name = raw?.trim()?.takeIf { it.isNotEmpty() }
        ?: return "Guest"
    return name.uppercase()
}

val buffer = mutableListOf("Kotlin")
val readView: List<String> = buffer
buffer.add("KMP")
// readView now observes both values
val snapshot = buffer.toList()
// independent list structure; element references are still shared

data class Quote(val id: String, val amountMinor: Long)
sealed interface LoadState {
    data object Loading : LoadState
    data class Ready(val quote: Quote) : LoadState
    data class Failed(val reason: String) : LoadState
}
fun label(s: LoadState): String = when (s) {
    LoadState.Loading -> "Loading"
    is LoadState.Ready -> s.quote.id
    is LoadState.Failed -> s.reason
}

fun eligibleIds(
    quotes: List<Quote>,
    allowed: (Quote) -> Boolean
): List<String> = quotes.filter(allowed).map { it.id }

val ids = eligibleIds(quotes) { it.amountMinor > 0 }
// quotes and Quote are caller-provided in this sketch

import kotlinx.coroutines.*

// Independent requests; APIs are supplied by the caller.
suspend fun load(profile: suspend () -> String,
                 offers: suspend () -> List<String>) = coroutineScope {
    val p = async { profile() }
    val o = async { offers() }
    p.await() to o.await()
}

import kotlinx.coroutines.flow.*

class Counter {
    private val mutable = MutableStateFlow(0)
    val state: StateFlow<Int> = mutable.asStateFlow()
    fun increment() = mutable.update { it + 1 }
}

